import test from 'node:test';
import assert from 'node:assert/strict';
import * as THREE from 'three';
import {Game} from '../src/game.js';
import {SAVE_KEY} from '../src/data.js';
import {loadSave} from '../src/persistence.js';
import {RUN_KEY,loadCheckpoint,normalizeCheckpoint} from '../src/checkpoint.js';

// Real Game constructor/start/finish/village/checkpoint methods with renderer/audio
// substitutes only. Checkpoints are generated by the game, never hand-invented.
function actualPendingNextRun(t){
 const globals=new Map(['window','document','localStorage'].map(key=>[key,Object.getOwnPropertyDescriptor(globalThis,key)]));
 t.after(()=>{for(const[key,descriptor]of globals)if(descriptor)Object.defineProperty(globalThis,key,descriptor);else delete globalThis[key];});
 const map=new Map(),failRead=new Set(),failRemove=new Set(),operations=[];let failPrimary=false;
 const storage={
  getItem(key){operations.push({type:'read',key});if(failRead.has(key))throw Error('QA read unavailable');return map.get(key)??null;},
  setItem(key,value){operations.push({type:'write',key});if(failPrimary&&key===SAVE_KEY)throw new DOMException('QA primary quota','QuotaExceededError');map.set(key,String(value));},
  removeItem(key){operations.push({type:'remove',key});if(failRemove.has(key))throw Error('QA remove unavailable');map.delete(key);}
 };
 globalThis.window={addEventListener(){}};
 globalThis.document={documentElement:{lang:'ko'},title:'',addEventListener(){}};
 globalThis.localStorage=storage;
 const world={actors:new THREE.Group(),cameraTarget:new THREE.Vector3(),updateBuildings(){},clearActors(){this.actors.clear();},setHome(){},setRegion(){},ring:()=>new THREE.Group()};
 const actor=()=>{const root=new THREE.Group();root.userData.model=new THREE.Group();root.add(root.userData.model);world.actors.add(root);return root;};world.castle=actor;world.enemy=actor;
 const game=new Game(world);game.ui={renderScreen(){},toast(){}};game.rebuildAttachments=()=>{};game.save.settings.sound=false;
 assert.equal(game.persist(),true);const initialPrimary=map.get(SAVE_KEY),initialSave=JSON.parse(initialPrimary);
 game.start();const runA=game.run.id,checkpointA=map.get(RUN_KEY);
 assert.equal(normalizeCheckpoint(JSON.parse(checkpointA),initialSave)?.run.id,runA);
 failPrimary=true;try{game.finish('retreat');}finally{failPrimary=false;}
 assert.equal(game.run.settled,false);assert.equal(game.run.outcome,'retreat');const pending=map.get(SAVE_KEY+':pending');assert.equal(JSON.parse(pending).id,runA);
 game.village(); // Legitimate next persist succeeds but leaves the old pending A journal.
 assert.equal(game.save.runs,1);assert.ok(game.save.settledRuns.includes(runA));assert.equal(map.get(SAVE_KEY+':pending'),pending);
 game.start();const runB=game.run.id;assert.notEqual(runA,runB);assert.equal(game.checkpointRun(),true);
 const checkpointB=map.get(RUN_KEY),backupB=map.get(RUN_KEY+':backup'),primaryBefore=map.get(SAVE_KEY);
 assert.equal(normalizeCheckpoint(JSON.parse(checkpointB),game.save)?.run.id,runB);
 assert.equal(normalizeCheckpoint(JSON.parse(backupB),game.save)?.run.id,runB);
 assert.equal(loadCheckpoint(game.save,storage)?.run.id,runB);
 return {game,storage,map,failRead,failRemove,operations,runA,runB,checkpointA,checkpointB,backupB,pending,initialPrimary,initialSave,primaryBefore};
}
function assertNativeB(fixture,recovered){
 assert.equal(fixture.map.get(RUN_KEY),fixture.checkpointB,'Unrelated B primary bytes must survive A recovery.');
 assert.equal(fixture.map.get(RUN_KEY+':backup'),fixture.backupB,'Unrelated B backup bytes must survive A recovery.');
 assert.equal(loadCheckpoint(recovered,fixture.storage)?.run.id,fixture.runB);
}

test('actual failed A settlement -> village persist -> native B checkpoint survives loadSave',t=>{
 const f=actualPendingNextRun(t),recovered=loadSave(f.storage);
 assert.equal(f.map.get(SAVE_KEY),f.primaryBefore,'Already settled A must not change the primary save.');
 assert.equal(recovered.coins,140);assert.equal(recovered.runs,1);assert.deepEqual(recovered.settledRuns,[f.runA]);
 assertNativeB(f,recovered);assert.equal(f.map.has(SAVE_KEY+':pending'),false);
});

test('pending A recovery removes both checkpoint slots owned by A',t=>{
 const f=actualPendingNextRun(t);f.storage.setItem(RUN_KEY,f.checkpointA);f.storage.setItem(RUN_KEY+':backup',f.checkpointA);
 const recovered=loadSave(f.storage);
 assert.equal(f.map.has(RUN_KEY),false);assert.equal(f.map.has(RUN_KEY+':backup'),false);assert.equal(f.map.has(SAVE_KEY+':pending'),false);
 assert.equal(loadCheckpoint(recovered,f.storage),null);assert.equal(recovered.runs,1);assert.equal(f.map.get(SAVE_KEY),f.primaryBefore);
});

for(const owned of [RUN_KEY,RUN_KEY+':backup'])test('pending A selectively removes only its '+(owned===RUN_KEY?'primary':'backup')+' checkpoint',t=>{
 const f=actualPendingNextRun(t),other=owned===RUN_KEY?RUN_KEY+':backup':RUN_KEY,otherBytes=f.map.get(other);
 f.storage.setItem(owned,f.checkpointA);const recovered=loadSave(f.storage);
 assert.equal(f.map.has(owned),false);assert.equal(f.map.get(other),otherBytes,'The B slot must not be cleared along with A.');
 assert.equal(loadCheckpoint(recovered,f.storage)?.run.id,f.runB);assert.equal(f.map.get(SAVE_KEY),f.primaryBefore);
});

test('valid unsettled A journal pays once across two recoveries while native B remains resumable',t=>{
 const f=actualPendingNextRun(t);
 // Unit settlement amounts, not a battle/difficulty claim. B checkpoint and all
 // its HP/time/stats/enemies remain exactly as produced by native Game.start.
 const pending={...JSON.parse(f.pending),coins:25,kills:2,time:20};
 f.storage.setItem(SAVE_KEY,f.initialPrimary);f.storage.setItem(SAVE_KEY+':backup',f.initialPrimary);f.storage.setItem(SAVE_KEY+':pending',JSON.stringify(pending));
 const first=loadSave(f.storage);assert.equal(first.coins,168);assert.equal(first.runs,1);assert.equal(first.totalKills,2);assert.equal(first.bestTime,20);assert.deepEqual(first.settledRuns,[f.runA]);
 assertNativeB(f,first);assert.equal(f.map.has(SAVE_KEY+':pending'),false);const paidPrimary=f.map.get(SAVE_KEY);
 f.storage.setItem(SAVE_KEY+':pending',JSON.stringify(pending)); // Journal survived/reappeared after a successful primary write.
 const second=loadSave(f.storage);assert.deepEqual(second,first);assert.equal(f.map.get(SAVE_KEY),paidPrimary);assertNativeB(f,second);assert.equal(f.map.has(SAVE_KEY+':pending'),false);
});

test('a checkpoint read failure preserves that slot and the unrelated native B backup',t=>{
 const f=actualPendingNextRun(t);f.failRead.add(RUN_KEY);const recovered=loadSave(f.storage);
 assert.equal(f.map.get(RUN_KEY),f.checkpointB);assert.equal(f.map.get(RUN_KEY+':backup'),f.backupB);assert.equal(loadCheckpoint(recovered,f.storage)?.run.id,f.runB);
 f.failRead.clear();assertNativeB(f,recovered);assert.equal(recovered.runs,1);assert.equal(recovered.coins,140);
});

test('a failed owned-slot removal does not prevent cleanup of the other owned A slot',t=>{
 const f=actualPendingNextRun(t);f.storage.setItem(RUN_KEY,f.checkpointA);f.storage.setItem(RUN_KEY+':backup',f.checkpointA);f.failRemove.add(RUN_KEY);
 const recovered=loadSave(f.storage);
 assert.equal(f.map.get(RUN_KEY),f.checkpointA,'Removal failure leaves the original owned bytes.');assert.equal(f.map.has(RUN_KEY+':backup'),false,'Other owned-slot cleanup must still be attempted.');
 assert.equal(recovered.runs,1);assert.equal(recovered.coins,140);assert.equal(loadCheckpoint(recovered,f.storage),null,'A settled checkpoint must remain non-resumable even if physical removal fails.');
});

test('a pending-journal removal failure cannot delete native B or duplicate the settled A reward',t=>{
 const f=actualPendingNextRun(t);f.failRemove.add(SAVE_KEY+':pending');const first=loadSave(f.storage);
 assertNativeB(f,first);assert.equal(f.map.get(SAVE_KEY+':pending'),f.pending);assert.equal(first.runs,1);assert.equal(first.coins,140);
 f.failRemove.clear();const second=loadSave(f.storage);assert.deepEqual(second,first);assertNativeB(f,second);assert.equal(f.map.has(SAVE_KEY+':pending'),false);
});
